void fillSij(FArray2D<std::complex<double>>& za, 
              FArray2D<std::complex<double>>& zb, 
              FArray2D<double>& s, 
              FArray2D<std::complex<double>>& aQQ_qb0, 
              FArray2D<std::complex<double>>& aQQ_QQb0, 
              FArray2D<std::complex<double>>& aq_qb0, 
              FArray2D<std::complex<double>>& aq_QQb0, 
              FArray2D<std::complex<double>>& SQQ_qb, 
              FArray2D<std::complex<double>>& SQQ_QQb) {

    using namespace constants_mod;
    using namespace epinv_mod;
    using namespace epinv2_mod;
    using namespace mxpart_mod;
    using namespace scale_mod;

    // Definition of helicity-dependent momenta
    const int q = 1, QQ = 2, qb = 3, QQb = 4, g = 5;
    const int r[2] = {q, qb};
    const int RR[2] = {QQ, QQb};

    auto epinv2Pij = [&](int i, int j) {
        return epinv * epinv2 + epinv * lnrat(musq, -s(i,j)) + half * lnrat(musq, -s(i,j)) * lnrat(musq, -s(i,j));
    };

    // Eq. (9)
    for (int i = 1; i <= 2; ++i) {
     for (int j = 1; j <= 2; ++j) {
        SQQ_qb(i, j) = -(
            xn * aQQ_qb0(i,j) * (epinv2Pij(qb, g) + epinv2Pij(QQb, q) + epinv2Pij(QQ, g))
            - one / xn * aQQ_qb0(i,j) * (-epinv2Pij(qb, QQb) + epinv2Pij(qb, QQ) + epinv2Pij(qb, q)
            + epinv2Pij(QQb, QQ) + epinv2Pij(QQb, q) - epinv2Pij(QQ, q))
            - one / xn * aQQ_QQb0(i,j) * (-epinv2Pij(qb, QQb) + epinv2Pij(qb, g)
            + epinv2Pij(QQb, q) - epinv2Pij(q, g))
            - one / xn * aq_qb0(i,j) * (epinv2Pij(QQb, q) - epinv2Pij(QQb, g)
            - epinv2Pij(QQ, q) + epinv2Pij(QQ, g)));
     }
    }

    // Eq. (10)
    for (int i = 1; i <= 2; ++i) {
     for (int j = 1; j <= 2; ++j) {
        SQQ_QQb(i, j) = -(
            xn * aQQ_QQb0(i,j) * (epinv2Pij(qb, q) + epinv2Pij(QQb, g) + epinv2Pij(QQ, g))
            - one / xn * aQQ_QQb0(i,j) * (-epinv2Pij(qb, QQb) + epinv2Pij(qb, QQ) + epinv2Pij(qb, q)
            + epinv2Pij(QQb, QQ) + epinv2Pij(QQb, q) - epinv2Pij(QQ, q))
            + xn * aQQ_qb0(i,j) * (epinv2Pij(qb, QQb) - epinv2Pij(qb, q)
            - epinv2Pij(QQb, g) + epinv2Pij(q, g))
            + xn * aq_QQb0(i,j) * (-epinv2Pij(qb, q) + epinv2Pij(qb, g)
            + epinv2Pij(QQ, q) - epinv2Pij(QQ, g)));
     }
    }

    return;
}

