     + za(j1, j2) * zb(j3, j4) * za(j4, j1) * za(j2, j4) * zb(j4, j5)
       / (six * s(j2, j3) * za(j3, j4) * za(j4, j5) * s(j5, j1));

  A51half = -(Vf + Vs) * miA5tree - (Ff + Fs); // @coverage-probe
  A51one = (Vg + four * Vf + Vs) * miA5tree + (four * Ff + Fs);
  return;
}

